window.ScripturaLexicons.BDAG_PART_0028 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anagignosko-bdag\" data-source=\"BDAG\" data-search=\"ἀναγιγνώσκω ἀναγινώσκω anagignosko anaginosko ler leitura pública ler em voz alta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναγι(γ)νώσκω</td><td>Verbo</td><td>ler; ler em voz alta</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anankazo-bdag\" data-source=\"BDAG\" data-search=\"ἀναγκάζω anankazo compelir forçar obrigar pressionar instar convidar fortemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναγκάζω</td><td>Verbo</td><td>compelir; forçar; pressionar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anankaios-bdag\" data-source=\"BDAG\" data-search=\"ἀναγκαῖος anankaios necessário necessidade íntimo parente amigo próximo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναγκαῖος</td><td>Adjetivo</td><td>necessário; íntimo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anankastos-bdag\" data-source=\"BDAG\" data-search=\"ἀναγκαστῶς anankastos compulsão por obrigação à força involuntariamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναγκαστῶς</td><td>Advérbio</td><td>por compulsão</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ananke-bdag\" data-source=\"BDAG\" data-search=\"ἀνάγκη ananke necessidade constrangimento pressão aflição calamidade tortura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάγκη</td><td>Substantivo feminino</td><td>necessidade; pressão; aflição</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anagnos-bdag\" data-source=\"BDAG\" data-search=\"ἄναγνος anagnos não casto incasto impuro sexualmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄναγνος</td><td>Adjetivo</td><td>não casto; impuro sexualmente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anagnorizo-bdag\" data-source=\"BDAG\" data-search=\"ἀναγνωρίζω anagnorizo reconhecer conhecer novamente reencontrar rever tornar a conhecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναγνωρίζω</td><td>Verbo</td><td>reconhecer; tornar a conhecer</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anagnosis-bdag\" data-source=\"BDAG\" data-search=\"ἀνάγνωσις anagnosis leitura leitura pública conteúdo lido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάγνωσις</td><td>Substantivo feminino</td><td>leitura; leitura pública</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anagraphe-bdag\" data-source=\"BDAG\" data-search=\"ἀναγραφή anagraphe registro público registros anais documentos oficiais BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναγραφή</td><td>Substantivo feminino</td><td>registro público; registros públicos</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anagrapho-bdag\" data-source=\"BDAG\" data-search=\"ἀναγράφω anagrapho registrar registro oficial inscrever lançar por escrito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναγράφω</td><td>Verbo</td><td>registrar; inscrever oficialmente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anago-bdag\" data-source=\"BDAG\" data-search=\"ἀνάγω anago levar para cima conduzir apresentar oferecer navegar zarpar restaurar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάγω</td><td>Verbo</td><td>levar para cima; conduzir; zarpar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anagogeus-bdag\" data-source=\"BDAG\" data-search=\"ἀναγωγεύς anagogeus condutor para cima guia ascendente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναγωγεύς</td><td>Substantivo masculino</td><td>aquele que conduz para cima</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anadeiknymi-bdag\" data-source=\"BDAG\" data-search=\"ἀναδείκνυμι anadeiknymi mostrar claramente revelar nomear designar comissionar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναδείκνυμι</td><td>Verbo</td><td>mostrar claramente; designar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anadeixis-bdag\" data-source=\"BDAG\" data-search=\"ἀνάδειξις anadeixis comissionamento instalação investidura nomeação pública BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάδειξις</td><td>Substantivo feminino</td><td>comissionamento; investidura</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anadechomai-bdag\" data-source=\"BDAG\" data-search=\"ἀναδέχομαι anadechomai aceitar receber assumir acolher hospedar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναδέχομαι</td><td>Verbo</td><td>aceitar; receber; acolher</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anadidomi-bdag\" data-source=\"BDAG\" data-search=\"ἀναδίδωμι anadidomi entregar transmitir passar dar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναδίδωμι</td><td>Verbo</td><td>entregar; transmitir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anazao-bdag\" data-source=\"BDAG\" data-search=\"ἀναζάω anazao voltar à vida ressuscitar reviver tornar-se ativo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναζάω</td><td>Verbo</td><td>voltar à vida; reviver</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anazeo-bdag\" data-source=\"BDAG\" data-search=\"ἀναζέω anazeo ferver borbulhar lama mundo inferior BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναζέω</td><td>Verbo</td><td>ferver; borbulhar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anazeteo-bdag\" data-source=\"BDAG\" data-search=\"ἀναζητέω anazeteo procurar buscar localizar por busca BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναζητέω</td><td>Verbo</td><td>procurar; buscar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anazonnumi-bdag\" data-source=\"BDAG\" data-search=\"ἀναζώννυμι anazonnumi cingir apertar cingir os lombos preparar-se ação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναζώννυμι</td><td>Verbo</td><td>cingir; apertar; preparar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anazoopyreo-bdag\" data-source=\"BDAG\" data-search=\"ἀναζωοπυρέω anazoopyreo variante ἀναζωπυρέω reacender 2 Timóteo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναζωοπυρέω</td><td>Verbo</td><td>veja ἀναζωπυρέω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anazopyreo-bdag\" data-source=\"BDAG\" data-search=\"ἀναζωπυρέω anazopyreo reacender reavivar inflamar novamente dom Deus fé BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναζωπυρέω</td><td>Verbo</td><td>reacender; reavivar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anathallo-bdag\" data-source=\"BDAG\" data-search=\"ἀναθάλλω anathallo florescer novamente reviver fazer florescer cuidado Filipenses BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀναθάλλω</td><td>Verbo</td><td>florescer novamente; fazer reviver</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-anathema-bdag\" data-source=\"BDAG\" data-search=\"ἀνάθεμα anathema oferta votiva amaldiçoado maldição anátema חרם BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀνάθεμα</td><td>Substantivo neutro</td><td>oferta votiva; coisa amaldiçoada; maldição</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-anagignosko-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναγι(γ)νώσκω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anagi(g)nṓskō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">No grego mais antigo, <span class=\"greek\">-γιγν-</span>; veja DELG s.v. <span class=\"greek\">γιγνώσκω</span>. Futuro <span class=\"greek\">ἀναγνώσομαι</span>; 2º aoristo <span class=\"greek\">ἀνέγνων</span>; infinitivo <span class=\"greek\">ἀναγνῶναι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.16</a>; particípio <span class=\"greek\">ἀναγνούς</span>. Passivo: futuro 3ª pl. <span class=\"greek\">ἀναγνωσθήσονται</span> — En 97.6 —; 1º aoristo <span class=\"greek\">ἀνεγνώσθην</span>; perfeito 3ª sg. <span class=\"greek\">ἀνέγνωσται</span> — Mel., <em>P.</em> 1 —; particípio <span class=\"greek\">ἀνεγνωσμένος</span>, LXX. Homero e posteriores. Literalmente, dos caracteres escritos, “conhecê-los de novo”: <strong>ler algo escrito ou inscrito, ler</strong>, normalmente em voz alta.</p>\n<p class=\"entry-text\"><strong>a.</strong> De modo geral — Píndaro, Tucídides e outros; PEleph 9, 3 [222 a.C.]; 13, 3; BGU 1079, 6ss. [séc. I d.C.]; veja Preis.; SIG 785, 1s. [séc. I d.C.]; LXX; Fílon, <em>Spec. Leg.</em> 4.160s.; Josefo, <em>Ant.</em> 11.98; Justino, <em>D.</em> 10.3; 11.3 e outros. Com indicação daquilo em que se lê: <span class=\"greek\">ἐν τῇ βίβλῳ</span>, <strong>no livro</strong> — TestDan 5.6 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.26</a>; <span class=\"greek\">ἐν τῷ νόμῳ</span>, <strong>na lei</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.5</a>; <span class=\"greek\">ἐν ταῖς γραφαῖς</span>, <strong>nas Escrituras</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.42\" target=\"_blank\" rel=\"noopener noreferrer\">21.42</a>.</p>\n<p class=\"entry-text\">Com acusativo — Josefo, <em>Ant.</em> 20.44 <span class=\"greek\">τὸν νόμον</span>; TestLevi 13.2 —: <span class=\"greek\">τὸ ῥηθέν</span>, <strong>o que foi dito</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22.31</a>; <span class=\"greek\">τὴν γραφὴν ταύτην</span>, <strong>esta passagem da Escritura</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.10</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.32</a>; <span class=\"greek\">τὸν τίτλον</span>, <strong>a inscrição</strong> — lat. <em>titulus</em> — sobre a cruz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.20</a>; <span class=\"greek\">Ἠσαΐαν</span>, <strong>Isaías</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.28</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.30\" target=\"_blank\" rel=\"noopener noreferrer\">30</a> — o eunuco lia em voz alta para si mesmo —; <span class=\"greek\">ἐπιστολήν</span>, <strong>uma carta</strong> — Diodoro Sículo 15.8.4; Josefo, <em>Vi.</em> 227 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4.16</a>; <span class=\"greek\">τοῦτο</span>, <strong>isto</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.3</a>; <span class=\"greek\">βιβλαρίδιον</span>, <strong>livrinho</strong>, Hv 2, 1, 3.</p>\n<p class=\"entry-text\">Com <span class=\"greek\">ὅτι</span> seguinte: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">21.16</a>. Com pergunta seguinte: <span class=\"greek\">ἀ. τί ἐποίησεν Δαυίδ</span>, <strong>ler o que Davi fez</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2.25</a>. <span class=\"greek\">πῶς ἀναγινώσκεις;</span>, <strong>como lês?</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10.26</a>.</p>\n<p class=\"entry-text\">Jogos de palavras — compare Platão, <em>Ep.</em> 2.312d <span class=\"greek\">ἵνα ὁ ἀναγνοὺς μὴ γνῷ</span>; Políbio 23.11.1 <span class=\"greek\">μὴ μόνον ἀναγινώσκειν τὰς τραγῳδίας … ἀλλὰ καὶ γινώσκειν</span>; POxy 1062, 13 [séc. II d.C.] <span class=\"greek\">αὐτὴν δέ σοι τὴν ἐπιστολὴν πέμψω διὰ Σύρου, ἵνα αὐτὴν ἀναγνοῖς νήφων καὶ σαυτοῦ καταγνοῖς</span> —: <span class=\"greek\">γινώσκεις ἃ ἀναγινώσκεις;</span>, <strong>entendes o que estás lendo?</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.30</a>; <span class=\"greek\">ἐπιστολὴ γινωσκομένη καὶ ἀναγινωσκομένη ὑπὸ πάντων ἀνθρώπων</span>, <strong>carta conhecida e lida por todos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3.2</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1.13</a>.</p>\n<p class=\"entry-text\">Absoluto: <span class=\"greek\">ὁ ἀναγινώσκων νοείτω</span>, <strong>que o leitor considere isto</strong> — assim Socratics p. 274, 26 Malherbe; PFay 20, 23; Sb 1019; 1020 e outros; Sir Prol. ln. 4 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13.14</a> — a acepção b também é possível aqui e em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1.3</a>, <span class=\"greek\">μακάριος ὁ ἀ.</span>, <strong>bem-aventurado o leitor deste livro</strong>. <span class=\"greek\">εἰρήνη τῷ γράψαντι καὶ τῷ ἀναγινώσκοντι</span>, <strong>paz ao escritor e ao leitor</strong>, GJs 25.2. O objeto costuma ser facilmente suprido: <span class=\"greek\">ἀναγνόντες</span> — isto é, <span class=\"greek\">τὴν ἐπιστολήν</span> — <span class=\"greek\">ἐχάρησαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.31</a>; <span class=\"greek\">ἀναγνοὺς</span> — isto é, <span class=\"greek\">τὴν ἐπιστολήν</span> — <span class=\"greek\">καὶ ἐπερωτήσας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.34\" target=\"_blank\" rel=\"noopener noreferrer\">23.34</a>; <span class=\"greek\">δύνασθε ἀναγινώσκοντες</span> — isto é, <span class=\"greek\">ἃ προέγραψα</span> — <span class=\"greek\">νοῆσαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3.4</a>; <span class=\"greek\">ἵνα καὶ ὑμεῖς ἀναγνῶτε</span> — isto é, <span class=\"greek\">τὴν ἐπιστολήν</span> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4.16</a>.</p>\n<p class=\"entry-text\"><strong>b.</strong> <strong>Ler em voz alta para audição pública</strong> — Xenofonte, <em>Cyr.</em> 4.5.26 e outros; PGrenf I, 37, 15 [séc. II a.C.]; POxy 59, 8; PCairGoodsp 29 III, l, testamento; SIG 883, 27; 789, 48; LXX; En 13.4; EpArist 310; Josefo, <em>Ant.</em> 4.209 <span class=\"greek\">ἀ. τοὺς νόμους ἅπασι</span>, compare 12.52; Justino, <em>D.</em> 67.3s.; Mel., <em>P.</em> 1, 1; 11, 72 —, da leitura das Escrituras nos cultos da sinagoga e da assembleia cristã. Compare Sb 7336, 29 [séc. III d.C.], <span class=\"greek\">ἀναγνώστῃ</span>, “para o leitor”, em festival de Sarápis, que provavelmente lia relatos de milagres de Sarápis — Aélio Aristides 45, 29s. K.</p>\n<p class=\"entry-text\">De Jesus: <span class=\"greek\">ἀνέστη ἀναγνῶναι</span>, <strong>levantou-se para ler a Escritura</strong> — GDalman, <em>Jesus-Jeshua</em>, trad. ingl. 1929, 38–55; veja também Billerb. IV, 1, 153–88 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.16</a>. <span class=\"greek\">Μωϋσῆς κατὰ πᾶν σάββατον ἀναγινωσκόμενος</span>, <strong>Moisés lido em voz alta todos os sábados</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.21</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">13.27</a>. <span class=\"greek\">ἡνίκα ἂν ἀναγινώσκηται Μωϋσῆς</span>, <strong>sempre que Moisés é lido</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3.15</a>.</p>\n<p class=\"entry-text\">Cartas dos apóstolos eram lidas nas reuniões cristãs desde época antiga — compare Diodoro Sículo 15.10.2, <span class=\"greek\">τὴν ἐπιστολὴν ἀναγνόντες</span>, <strong>depois de terem lido a carta em voz alta</strong>; compare POxy 2787, 14s. [séc. II d.C.] —: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5.27</a>. O final da sexta carta de Platão, 323c, traz o pedido <span class=\"greek\">ταύτην τ. ἐπιστολὴν πάντας ὑμᾶς ἀναγνῶναι χρή</span>. <span class=\"greek\">ἀναγινώσκω ὑμῖν ἔντευξιν</span>, 2 Cl 19.1; <span class=\"greek\">παραβολάς</span>, Hv 5.5 — a acepção a acima também é provável aqui. Absoluto: v 1, 3, 3; 2, 4, 3. <span class=\"greek\">ἐτέλεσεν ἀναγινώσκουσα</span>, <strong>ela parou de ler em voz alta</strong>, v 1, 4, 1. Provavelmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13.14</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1.3</a> também pertencem aqui — veja a. — PGlaue, <em>Die Vorlesung hl. Schriften im Gottesdienste</em> I 1907. — B. 1284. M-M. TW. Sv.</p>\n</section></article><article id=\"entry-anankazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναγκάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anankázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Denominativo de <span class=\"greek\">ἀνάγκη</span>. Imperfeito <span class=\"greek\">ἠνάγκαζον</span>; futuro <span class=\"greek\">ἀναγκάσω</span>, LXX; 1º aoristo <span class=\"greek\">ἠνάγκασα</span>; imperativo <span class=\"greek\">ἀνάγκασον</span>. Passivo: 1º aoristo <span class=\"greek\">ἠναγκάσθην</span>; particípio perfeito passivo <span class=\"greek\">ἠναγκασμένη</span>, 4 Macc 15.7. Sófocles, Heródoto, Tucídides e posteriores; inscrições, papiros, LXX, TestSol; TestJob 12.2; EpArist; Fílon, <em>Aet. M.</em> 136; Josefo; Justino; POxy 1778 [Ar.] 14s.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Compelir alguém a agir de determinado modo, compelir, forçar</strong>, de compulsão interior ou exterior; seguido de infinitivo — Ps.-Platão, <em>Sisyphus</em> 1 p. 387b, <span class=\"greek\">ξυμβουλεύειν αὑτοῖς ἠνάγκαζόν με</span>, <strong>tentaram compelir-me a fazer causa comum com eles</strong>; Josefo, <em>Ant.</em> 12.384s.; Crates p. 56, 12 Malherbe —; 1 Cl 4.10. <span class=\"greek\">ἠνάγκαζον βλασφημεῖν</span>, <strong>eu tentava forçá-los a blasfemar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 26.11</a>. <span class=\"greek\">τὰ ἔθνη ἀ. ἰουδαΐζειν</span>, <strong>compelir os gentios a viver à maneira judaica</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2.14</a>. <span class=\"greek\">οὐκ ἠναγκάσθη περιτμηθῆναι</span>, <strong>não foi compelido a ser circuncidado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2.3</a> — veja Josefo, <em>Vi.</em> 113 —; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">6.12</a>, onde a acepção 2 é provável.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἠναγκάσθην ἐπικαλέσασθαι Καίσαρα</span>, <strong>fui obrigado a apelar para César</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.19</a> — compare Mel., <em>P.</em> 94, 720 <span class=\"greek\">λέγειν ἀναγκάζομαι</span>; BGU 180, 16. <span class=\"greek\">ἀ. αὐτοὺς πεισθῆναι σοι</span>, <strong>eu os compelirei a obedecer-te</strong>, Hm 12, 3, 3. Com <span class=\"greek\">εἴς τι</span> em lugar do infinitivo: <span class=\"greek\">ἀναγκάζομαι εἰς τοῦτο</span>, <strong>sou forçado a fazer isto</strong>, B 1.4. Com infinitivo subentendido: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12.11</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Em sentido enfraquecido, <strong>instar/convidar fortemente, pressionar</strong> — POxy 1069, 2; 20; compare HPernot, <em>Études sur la langue des Évang.</em> 1927; <em>ET</em> 38, 1927, 103–8 —, com acusativo e infinitivo — Diógenes Laércio 1.26 <span class=\"greek\">τ. μητρὸς ἀναγκαζούσης αὐτὸν γῆμαι</span> —: <span class=\"greek\">ἠνάγκασεν τ. μαθητὰς ἐμβῆναι</span>, <strong>pressionou os discípulos a embarcar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.45</a>. Com o acusativo suprido pelo contexto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.23</a>. — M-M. TW.</p>\n</section></article><article id=\"entry-anankaios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναγκαῖος</h1><div class=\"entry-meta\"><span class=\"greek\">α, ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anankaîos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Homero e outros, em vários sentidos.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Necessário</strong>, como aquilo que satisfaz uma necessidade. <span class=\"greek\">τὰ μέλη τοῦ σώματος ἀ. ἐστιν</span>, <strong>os membros do corpo são necessários</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12.22</a>; compare 1 Cl 37.5. <span class=\"greek\">αἱ ἀ. χρεῖαι</span>, <strong>necessidades prementes</strong> — Diodoro Sículo 1.34; IPriene 108, 80 [c. 129 a.C.]; POxy 56, 6; 1068, 16; Fílon, <em>Omn. Prob. Lib.</em> 76; Atanásio 22.4, <span class=\"greek\">τῶν ἀναγκαίων</span>, “órgãos genitais” —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3.14</a>.</p>\n<p class=\"entry-text\">Neutro <span class=\"greek\">ἀναγκαῖόν ἐστιν</span>, <strong>é necessário</strong>, seguido de infinitivo — e acusativo —: PFlor 132, 11 <span class=\"greek\">ὅπερ ἀναγκαῖόν σε ἦν γνῶναι</span>; Fílon, <em>Migr. Abr.</em> 82; Josefo, <em>Vi.</em> 413; Justino, <em>D.</em> 68.4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.46\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.46</a>. <span class=\"greek\">ἀ. ἡγοῦμαι</span>, <strong>considero necessário</strong> — PFay 111, 19; SIG 867, 9 <span class=\"greek\">ἀναγκαῖον ἡγησάμην … φανερὸν ποιῆσαι</span>; 2 Macc 9.21 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2.25</a>. <span class=\"greek\">ἀ. ἐστιν, μηδὲν πράσσειν ὑμᾶς</span>, ITr 2.2. <span class=\"greek\">ὅθεν ἀναγκαῖον</span>, com <span class=\"greek\">ἐστίν</span> subentendido — como EpArist 197; 205 —, <span class=\"greek\">ἔχειν τι τοῦτον</span>, <strong>portanto, este deve ter alguma coisa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8.3</a>.</p>\n<p class=\"entry-text\">Comparativo — PLond I, 42, 31 p. 31; Witkowski 36, 21 —: <span class=\"greek\">ἀναγκαιότερόν ἐστιν</span>, <strong>é mais necessário</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.24</a>. Substantivado em referência à defecação: <span class=\"greek\">δι’ αὐτῶν μόνων τῶν ἀ.</span>, Papias (3:2).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Íntimo, próximo</strong>, como o latim <em>necessarius</em> de parentes e amigos: <span class=\"greek\">τοὺς ἀ. φίλους</span>, <strong>amigos íntimos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.24</a> — compare Eurípides, <em>Andr.</em> 671; Dio Crisóstomo 3.120; SIG 1109, 51; POslo 60, 5 [séc. II d.C.]; PFlor 142, 2; BGU 625, 26; Josefo, <em>Ant.</em> 7.350; 11.254. — EDNT. M-M. TW. Spicq. Sv.</p>\n</section></article><article id=\"entry-anankastos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναγκαστῶς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anankastō̂s⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἀναγκάζω</span>; Ps.-Platão, <em>Axioch.</em> 366a. Advérbio de <span class=\"greek\">ἀναγκαστός</span> — Heródoto e outros; Josefo, <em>Ant.</em> 18.37 —: <strong>por compulsão, por obrigação</strong>, em oposição a <span class=\"greek\">ἑκουσίως</span>, “voluntariamente”: <span class=\"greek\">ποιμαίνειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 5.2</a>. O modelo da pessoa de espírito cívico que se oferece voluntariamente está subjacente à linha de pensamento. — M-M.</p>\n</section></article><article id=\"entry-ananke-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάγκη</h1><div class=\"entry-meta\"><span class=\"greek\">ης, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anánkē⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Homero e posteriores; inscrições, papiros, LXX, En; PsSol 5.6; TestJob 12.3; TestJos 2.4; ApcSed 10.4; ApcMos 25; Fílon, Josefo, Ar., Justino; Mel. Fgm. 6, 5; Atanásio. No Novo Testamento nunca ocorre no sentido excepcional de <strong>destino</strong> — por exemplo, Eurípides, <em>Ph.</em> 1000.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Necessidade ou constrangimento inerentes à natureza das coisas; necessidade, pressão de qualquer espécie</strong>, incluindo uma disposição divina, alguma vantagem esperada, costume, dever etc. — Apiano, <em>Bell. Civ.</em> 5.17 §68 <span class=\"greek\">ἀ. νόμων</span>; Museu 289, do amor; Crates p. 54, 15 e outros Malherbe; SibOr 3.101; 296; Justino, <em>D.</em> 44.11. <span class=\"greek\">ἄνευ ζυγοῦ ἀνάγκης</span>, <strong>sem o jugo da necessidade</strong>, B 2.6.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀνάγκη</span>, com <span class=\"greek\">ἐστὶν</span> subentendido: <strong>é necessário, é inevitável, deve-se</strong>, com infinitivo, ou acusativo e infinitivo — Heródoto 2.35; SIG 888, 79; BGU 665 II, 16; Justino, <em>A I</em> 21.4 e outros; Atanásio 17.1 e outros; Dídimo, <em>Gen.</em> 104, 29. <span class=\"greek\">ἀ. (ἐστὶν [v.l.]) ἐλθεῖν τὰ σκάνδαλα</span>, <strong>as tentações devem vir</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18.7</a>. <span class=\"greek\">διὸ ἀ.</span>, <strong>portanto é necessário que vos sujeiteis</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13.5</a>. <span class=\"greek\">θάνατον ἀ. (ἐστὶν) φέρεσθαι τοῦ διαθεμένου</span>, <strong>a morte do testador deve ser anunciada</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.16</a>; compare v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a>. Com <span class=\"greek\">ἐστί</span> e sem infinitivo: <span class=\"greek\">εἰ ἀ. ἐστί</span>, Hs 9, 9, 3; <span class=\"greek\">ἐὰν ᾖ ἀ.</span>, D 12.2.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀ. ἔχω</span> com infinitivo — Plutarco, <em>Cato Min.</em> 24.6; Josefo, <em>Ant.</em> 16.290, <em>Vi.</em> 171 e outros; TestJob 10.3; 12.3 e outros; POxy 1061, 4 [22 a.C.]; PFlor 278 IV, 23; compare <em>New Docs</em> 1, 45 —: <strong>devo</strong>; <span class=\"greek\">ἰδεῖν αὐτόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.18</a>; <span class=\"greek\">ἀπολύειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">23.16 [17]</a> v.l.; <span class=\"greek\">γράψαι ὑμῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 3</a>; <span class=\"greek\">θυσίας ἀναφέρειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7.27</a>; <span class=\"greek\">αἰτεῖσθαι</span>, Hs 5, 4, 5; <span class=\"greek\">ἐρωτᾶν</span>, 9, 14, 4; compare 9, 16, 2. Sem infinitivo: <span class=\"greek\">μὴ ἔχων ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7.37</a>. <span class=\"greek\">ἀ. μοι ἐπίκειται</span> — Ilíada 6.458 —, <strong>estou sob obrigação</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">9.16</a>.</p>\n<p class=\"entry-text\">Com preposição: <span class=\"greek\">ἐξ ἀνάγκης</span>, <strong>sob pressão</strong> — trágicos, Tucídides; Epicteto 2.20.1; Josefo, <em>Bell.</em> 5.568; Atanásio, <em>R.</em> 66, 17; Dídimo, <em>Gen.</em> 75, 21; POxy 237 IV, 33; PIand 19, 1 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9.7</a>; ou <strong>necessariamente, logicamente</strong> — Diodoro Sículo 1.80.3; Dio Crisóstomo 21 [38], 31; 34; Fílon, <em>Aet. M.</em> 21; 52 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7.12</a>; Hs 7.3. Pleonasticamente <span class=\"greek\">δεῖ ἐξ ἀ.</span>, m 6, 2, 8; Hs 9, 9, 2. <span class=\"greek\">ὡς κατὰ ἀνάγκην</span>, em oposição a <span class=\"greek\">κατὰ ἑκούσιον</span>, <strong>como que sob pressão</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 14</a> — compare Xenofonte, <em>Cyr.</em> 4.3.7; Artem. 5.23; EpArist 104; 2 Macc 15.2; Josefo, <em>Ant.</em> 3.223; Ar.; Justino, <em>A I</em> 30.1; Atanásio 24.2; PCairMasp 66, 2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Estado de aflição ou dificuldade; aflição, calamidade, pressão</strong>, uso característico do grego posterior — Diodoro Sículo 10.4.6, “perigo mortal”; Apiano, <em>Bell. Civ.</em> 5.40 §167 <span class=\"greek\">ἐσχάτη ἀ.</span>; LXX; Josefo, <em>Bell.</em> 5.571; <em>Ant.</em> 2.67; também como empréstimo no rabínico. Da aflição nos últimos dias: <span class=\"greek\">ἀ. μεγάλη</span>, <strong>grande aflição</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21.23</a>. <span class=\"greek\">ἡ ἐνεστῶσα ἀ.</span>, <strong>a aflição presente</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7.26</a>. A expressão “aflição presente” encontra-se em Epicteto 3.26.7; 3 Macc 1.16 v.l. e PGM 4, 526s.; em Antifonte 6.25 a compulsão presente é chamada <span class=\"greek\">ἡ παροῦσα ἀνάγκη</span>. Veja KBenz, <em>TGl</em> 10, 1918, 388ss.; PTischleder, ibid. 12, 1920, 225ss.</p>\n<p class=\"entry-text\">Com <span class=\"greek\">θλῖψις</span> — como Jó 15.24 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 3.7</a>. Plural, <strong>pressões</strong> — Antifonte 6.25; Herodas 5.59; Diodoro Sículo 4.43.5; 10.17.1; SIG 521, 23 [séc. III a.C.]; Cat. Cod. Astr. VII 143, 23; VIII/3, 182, 17; 185, 27; LXX; Fílon, <em>Rer. Div. Her.</em> 41; Josefo, <em>Ant.</em> 16.253; TestJos 2.4 —, com <span class=\"greek\">θλίψεις, στενοχωρίαι</span> etc., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6.4</a>; com <span class=\"greek\">διωγμοί</span> e <span class=\"greek\">στενοχωρίαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">12.10</a> — mas veja 3 abaixo. Nos catálogos paulinos de sofrimentos emerge o tema do benfeitor em perigo, que arrisca muito por seu público; veja AFridrichsen, “Zum Stil des Paulinischen Peristasenkatalogs”, <em>SymbOsl</em> 7, 1928, 25–29; Danker, <em>Benefactor</em> 363–64. <span class=\"greek\">ἐξ ἀναγκῶν ἐξαιρεῖσθαι</span>, <strong>livrar de calamidades</strong>, 1 Cl 56.8 — Jó 5.19. Para isso, <span class=\"greek\">ἐξ ἀναγκῶν λυτροῦσθαι τοὺς δούλους τοῦ θεοῦ</span>, Hm 8.10.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> Concretização do abstrato: <strong>compulsão por meios violentos, tortura</strong> — referências em AFridrichsen, <em>ConNeot</em> 9, 1944, 28s. e L-S-J-M s.v. 3 —; esta acepção é provável em algumas passagens, por exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12.10</a> — veja 2 acima. — HSchreckenburg, <em>Ananke</em>, 1964. — B. 638. DELG. DDD s.v. <em>Ananke</em>. M-M. TW. Sv.</p>\n</section></article><article id=\"entry-anagnos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄναγνος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ánagnos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ἁγνός</span>, “puro”. Trágicos e outros; CB I/1, 149 nº 41, “ritualmente impuro”; Fílon, <em>Cher.</em> 94; Josefo, <em>C. Ap.</em> 1.306; SibOr 3.496s. <strong>Não casto, impuro sexualmente</strong>. Com <span class=\"greek\">μιαρός</span>, como em Antifonte, <em>Tetral.</em> 1, 1, 10 Blass, <span class=\"greek\">μιαρὸν κἄναγνον</span>: <span class=\"greek\">συμπλοκαί</span>, <strong>abraços em relações sexuais</strong>, 1 Cl 30.1 — compare Ptolemeu, <em>Apotel.</em> 3.14.17 <span class=\"greek\">τὰς συνουσίας ἀνάγνους</span>. — DELG s.v. <span class=\"greek\">ἅζομαι</span>.</p>\n</section></article><article id=\"entry-anagnorizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναγνωρίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anagnōrízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo médio <span class=\"greek\">ἀνεγνωρισάμην</span>. De <span class=\"greek\">γνωρίζω</span>, “tornar conhecido”; Platão, <em>Polit.</em> 258a; Herm. Wr. 1.18; Gn 45.1. <strong>Aprender a conhecer de novo, tornar a familiarizar-se; ver novamente</strong>: <span class=\"greek\">ταύτην</span>, Hv 1, 1, 1. No passivo, <strong>ser reconhecido</strong>: <span class=\"greek\">ἀνεγνωρίσθη Ἰωσὴφ τ. ἀδελφοῖς αὐτοῦ</span>, <strong>José foi reconhecido por seus irmãos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.13</a> — Gn 45.1. — DELG s.v. <span class=\"greek\">γιγνώσκω</span> 225.</p>\n</section></article><article id=\"entry-anagnosis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάγνωσις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anágnōsis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Heródoto e outros; Sir Prol. 10, 17; EpArist; Fílon; Josefo, <em>C. Ap.</em> 2.147. Sentido primário: “conhecer novamente”; depois, “leitura”.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>O processo de ler algo escrito, leitura</strong> — veja <span class=\"greek\">ἀναγι(γ)νώσκω</span> —, especialmente da leitura pública: Platão; SIG 695, 81; papiros; LXX — 1 Esdr 9.48; 2 Esdr 18.8 —; EpArist 127; 283; 305. Da leitura da Lei e dos Profetas na sinagoga — compare a inscrição sinagogal de Jerusalém, SEG VIII, 170, 4 <span class=\"greek\">συναγωγὴν εἰς ἀνάγνωσιν νόμου</span> —: <span class=\"greek\">μετὰ τὴν ἀ. τ. νόμου καὶ τ. προφητῶν</span>, <strong>depois da leitura da Lei e dos Profetas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.15</a>. <span class=\"greek\">ἡ ἀ. τῆς παλαιᾶς διαθήκης</span>, <strong>a leitura pública do Antigo Testamento</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3.14</a>.</p>\n<p class=\"entry-text\">Os cristãos também conheciam a leitura pública: <span class=\"greek\">πρόσεχε τῇ ἀ., τῇ παρακλήσει, τῇ διδασκαλίᾳ</span>, <strong>dedica-te à leitura pública, à exortação e ao ensino</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 4.13</a>. Compare WBauer, <em>D. Wortgottesdienst d. ältesten Christen</em> 1930, 39–54.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>O conteúdo daquilo que é lido, leitura</strong>: <span class=\"greek\">ἤρεσέν σοι ἡ ἀ. μου;</span>, <strong>agradou-te a minha leitura, isto é, aquilo que li?</strong>, Hv 1, 4, 2. — M-M. TW.</p>\n</section></article><article id=\"entry-anagraphe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναγραφή</h1><div class=\"entry-meta\"><span class=\"greek\">ῆς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anagraphḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">γραφή</span>, “escrita”. Platão, Xenofonte e outros; inscrições, papiros, EpArist, Fílon; Taciano 31.4. Literalmente, <strong>aquilo que é posto por escrito</strong>; no plural, <strong>registros públicos</strong> — Políbio; Diodoro Sículo 1.31.7 <span class=\"greek\">ἐν ταῖς ἱεραῖς ἀναγραφαῖς</span>; Plutarco; Josefo, <em>C. Ap.</em> 1.28; 2 Macc 2.13; GDI 1743, 10. <span class=\"greek\">ἐπισκέπτεσθαι τὰς ἀ. τῶν χρόνων</span>, <strong>examinar os registros das datas</strong>, 1 Cl 25.5. Diodoro Sículo 16.51.2 emprega o termo para antigos documentos em templos egípcios; trata-se de termo técnico para publicações oficiais. Veja AWilhelm, <em>Sd.-Schrift österr. Archäol. Inst.</em> 7, 1909, 271ss.</p>\n</section></article><article id=\"entry-anagrapho-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναγράφω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anagráphō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro 1ª pl. <span class=\"greek\">ἀναγράψομεν</span> — Taciano 41.3 —; 1º aoristo <span class=\"greek\">ἀνέγραψα</span>. Passivo: 2º aoristo <span class=\"greek\">ἀνεγράφην</span> — Justino, Taciano —; perfeito 3ª sg. <span class=\"greek\">ἀναγέγραπται</span>. Heródoto e posteriores.</p>\n<p class=\"entry-text\"><strong>Fazer um registro oficial, registrar, inscrever</strong>, termo técnico jurídico — SIG 679, 19. <span class=\"greek\">εἰ αὕτη μοι ἡ ἁμαρτία ἀναγράφεται</span>, <strong>se este pecado é registrado contra mim</strong>, isto é, no livro do julgamento — compare Esopo, <em>Fab.</em> 317, 17 P. = Bábrio 75 L-P., sobre registros em livros no mundo inferior —, Hv 1, 2, 1.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀναγραφῖσα</span> em lugar de <span class=\"greek\">ἀνατραφῖσα</span> é erro de transcrição em GJs 13.2; 15.3.</p>\n</section></article><article id=\"entry-anago-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάγω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anágō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀνάξω</span>, LXX; 2º aoristo <span class=\"greek\">ἀνήγαγον</span>; 1º aoristo passivo <span class=\"greek\">ἀνήχθην</span>. Homero e posteriores; inscrições, papiros, LXX, En 28.3; TestSol; TestAbr; Test12Patr; Fílon; Josefo; Justino; Mel. Fgm. 9, 6; Atanásio 11.2, <span class=\"greek\">ἐπὶ παρρησίαν ἀναγαγεῖν</span>, “elevar a voz a um tom de ousadia”.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Conduzir ou trazer de um ponto inferior para outro superior; conduzir, levar para cima</strong>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.5</a> — <span class=\"greek\">εἰς ὄρος ὑψηλόν</span> v.l. —; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17.1</a> D; <span class=\"greek\">εἰς Ἱεροσόλυμα</span>, <strong>para Jerusalém</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.22</a> — compare Josefo, <em>Bell.</em> 1.96. <span class=\"greek\">ἀνήχθη εἰς τὴν ἔρημον</span>, <strong>foi conduzido para cima, ao deserto</strong>, do Jordão — abaixo do nível do mar — para a região elevada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.1</a>, a menos que se entenda que ele foi “arrebatado”; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12.2</a> v.l. <span class=\"greek\">ὡς ἀνήγεσθε</span>; Mel., <em>P.</em> 103, 798 <span class=\"greek\">εἰς τὰ ὑψηλὰ τῶν οὐρανῶν</span>.</p>\n<p class=\"entry-text\"><span class=\"greek\">εἰς τὸ ὑπερῷον</span>, <strong>para o aposento superior</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.39</a>; <span class=\"greek\">εἰς τὸν οἶκον</span>, <strong>para o interior da casa</strong>, visto que os cômodos do porão serviam de prisão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 16.34</a>; <span class=\"greek\">ἐν ναῷ</span>, <strong>no templo</strong>, GJs 7.1.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀ. ἐκ νεκρῶν</span>, <strong>trazer para cima, dentre os mortos</strong>, sendo o domínio dos mortos representado como subterrâneo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13.20</a>; compare Luciano, <em>Dial. Mort.</em> 23.6; 1 Km 2.6; 28.11; Tb 13.2; Sl 29.4; Justino, <em>D.</em> 32.3, <span class=\"greek\">ἀνάγοντα αὐτὸν [Χριστόν] ἀπὸ τῆς γῆς</span>. Figuradamente, com <span class=\"greek\">εἴς τι</span> — como João de Sardes, <em>Comm. in Aphth.</em> p. 4, 10 Rabe [1928] —, do amor: <span class=\"greek\">τὸ ὕψος εἰς ὃ ἀνάγει ἡ ἀγάπη</span>, <strong>a altura à qual o amor conduz</strong>, 1 Cl 49.4.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Levar para um processo judicial, fazer comparecer</strong>, termo técnico jurídico — Xenofonte, <em>Hell.</em> 3.3.11; Políbio 40.4.2; SIG 799, 24 [38 d.C.] <span class=\"greek\">ἀναχθέντα εἰς τ. δῆμον</span>; OGI 483, 185 [Pérgamo]; PMagd 33, 8; PTebt 43, 19; TestAbr A 15 p. 95, 9 [Stone p. 38] —; <span class=\"greek\">τινά τινι</span>, alguém diante de alguém — Josefo, <em>Ant.</em> 12.390 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.4</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Trazer uma oferta, oferecer</strong>: <span class=\"greek\">ἀ. θυσίαν</span>, <strong>oferecer um sacrifício</strong>. O emprego do termo sugere procedimento festivo; compare Heródoto 2.60; 6.111; OGI 764, 47 [c. 127 a.C.] <span class=\"greek\">ἀναγαγὼν … ταύρους δύο</span>; 3 Km 3.15; Fílon, <em>Agr.</em> 127; <em>Mos.</em> 2.73 e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.41\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.41</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> Como termo técnico náutico — <span class=\"greek\">ἀ. τὴν ναῦν</span>, “pôr um navio ao mar” —, no médio ou passivo <span class=\"greek\">ἀνάγεσθαι</span>: <strong>começar a viajar de barco, fazer-se ao mar, zarpar</strong> — Heródoto, Demóstenes; também Políbio 1.21.4; 1.23.3 e outros; papiros, Mayser 380; Josefo, <em>Bell.</em> 3.502. <span class=\"greek\">ἀνήχθημεν ἐν πλοίῳ</span>, <strong>fizemo-nos ao mar num navio</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.11</a>. <span class=\"greek\">ἀ. ἀπὸ τῆς Πάφου</span>, <strong>partir de Pafos</strong> — compare Epicteto 3.21.12 <span class=\"greek\">ἀ. ἀπὸ λιμένος</span> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.13</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">16.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">18.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.21\" target=\"_blank\" rel=\"noopener noreferrer\">27.21</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐκεῖθεν</span>, <strong>dali</strong> — Josefo, <em>Ant.</em> 14.377 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.4</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a>. Com o curso indicado: <span class=\"greek\">εἰς τὴν Συρίαν</span>, <strong>para a Síria</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 20.3</a> — compare BGU 1200, 14 [séc. I a.C.] <span class=\"greek\">ἀ. εἰς Ἰταλίαν</span> —; <span class=\"greek\">ἐπὶ τὴν Ἆσσον</span>, <strong>para Assos</strong>, v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>. Absoluto: <span class=\"greek\">ἀνήχθησαν</span>, <strong>zarparam</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.22</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.1s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.2\" target=\"_blank\" rel=\"noopener noreferrer\">27.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.10\" target=\"_blank\" rel=\"noopener noreferrer\">28.10</a>; AcPl Ha 7, 13; Justino, <em>D.</em> 142.2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">5.</span> <strong>Reconduzir a um estado ou condição anterior, restaurar, trazer de volta</strong>, figuradamente — em papiros, da melhoria do solo —: <span class=\"greek\">τοὺς ἀσθενοῦντας περὶ τὸ ἀγαθόν</span>, <strong>restaurar os que são fracos quanto ao bem</strong>, 2 Cl 17.2. — M-M. TW.</p>\n</section></article><article id=\"entry-anagogeus-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναγωγεύς</h1><div class=\"entry-meta\"><span class=\"greek\">έως, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anagōgeús⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Sobre a forma <span class=\"greek\">ἀγωγεύς</span>, veja DELG s.v. <span class=\"greek\">ἄγω</span> 18. Literalmente, “aquilo que leva para cima”, como das correias que mantêm uma sandália no lugar — Aélio, <em>VH</em> 9.11; Ateneu 543f —; <strong>aquele que conduz para cima</strong> — Proclo, sobre Platão, <em>Tim.</em> I p. 34, 20 Diehl, de Hermes; <em>Hymni</em> 1, 34 [<em>Orphica</em> p. 277 Abel], de Hélio, <span class=\"greek\">ψυχῶν ἀναγωγεύς</span>, “condutor das almas para cima”.</p>\n<p class=\"entry-text\">Em nossa literatura, somente figuradamente: <span class=\"greek\">ἡ πίστις ὑμῶν ἀ. ὑμῶν</span>, <strong>a vossa fé é quem vos conduz para cima</strong>, IEph 9.1 — veja <em>Hdb.</em> ad loc. A interpretação “guincho” de Lightfoot e outros parece improvável. — TW.</p>\n</section></article><article id=\"entry-anadeiknymi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναδείκνυμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anadeíknumi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀναδείξω</span>, LXX; 1º aoristo <span class=\"greek\">ἀνέδειξα</span>; perfeito <span class=\"greek\">ἀναδέδειχα</span>, LXX. Passivo: futuro <span class=\"greek\">ἀναδειχθήσομαι</span>; 1º aoristo <span class=\"greek\">ἀνεδείχθην</span>; particípio perfeito <span class=\"greek\">ἀναδεδειγμένος</span>, todas estas formas passivas na LXX. Sófocles, Heródoto e outros; inscrições, LXX; TestJos 2.7; Fílon, <em>Sacr. Abel.</em> 35; Josefo; Taciano. Sentido básico: “mostrar para fora”.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Tornar algo conhecido por indicação clara, mostrar claramente, revelar algo oculto</strong> — compare IAndrosIsis, Ios 19 Peek p. 123; 2 Macc 2.8; SibOr 3.15 —: <span class=\"greek\">τινά</span>, alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.24</a>; <span class=\"greek\">πῶς</span>, Ox 1081, 31s. — SJCh 90, 70s. Com <span class=\"greek\">ἐν</span>, <strong>exibir, mostrar algo em algo</strong>: <span class=\"greek\">ἵνα δικαιοσύνης ναὸν ἐν τῷ τοίῳ σώματι ἀναδείξῃ</span>, <strong>para mostrar o templo da retidão nesse mesmo corpo</strong>, AcPlCor 2.17.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Designar para uma tarefa ou posição, nomear, comissionar</strong>, frequentemente como termo administrativo — veja o verbete seguinte; Políbio 4.48.3; 4.51.3; Diodoro Sículo 1.66.1; 13.98.1; Plutarco, <em>Caes.</em> 725 [37.2]; OGI 625, 7; PErl 18, 19; Dn 1.11, 20; 1 Esdr 8.23; 2 Macc 9.23, 25 e outros; Josefo, <em>Ant.</em> 14.280; 20.227; Taciano 7.2, <span class=\"greek\">θεόν</span>, como Deus. <span class=\"greek\">ἀνέδειξεν</span> — <span class=\"greek\">ἐνέδ.</span> P75 — <span class=\"greek\">ὁ κύριος ἑτέρους ἑβδομήκοντα</span>, <strong>o Senhor designou outros setenta</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10.1</a>. — EPeterson, <em>Deissmann Festschr.</em> 1927, 320–26. — M-M. TW.</p>\n</section></article><article id=\"entry-anadeixis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάδειξις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anádeixis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Políbio e outros; ERoberts e EGardner, <em>Introd. to Gk. Epigraphy</em> II 1905, 119; SB 7346, 8 [?]; Sir 43.6. <strong>Comissionamento, investidura</strong>, termo técnico referente ao reconhecimento público de uma autoridade nomeada — Políbio 15.26.7; Plutarco, <em>Mar.</em> 804 [8.5]; veja <span class=\"greek\">ἀναδείκνυμι</span> 2. <span class=\"greek\">ἕως ἡμέρας ἀναδείξεως αὐτοῦ πρὸς τὸν Ἰσραήλ</span>, <strong>até o dia em que foi comissionado diante de Israel</strong>, como precursor do Messias — compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3.2</a>; Diodoro Sículo 1.85, de Osíris —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.80\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.80</a>. — EBickerman, “Ἀνάδειξις”, <em>Mélanges EBoisacq</em> I, 1937, 117–24. DELG s.v. <span class=\"greek\">δείκνυμι</span>. TW. Spicq. Sv.</p>\n</section></article><article id=\"entry-anadechomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναδέχομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anadéchomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἀνεδεξάμην</span>. Homero e posteriores.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Experimentar algo mediante aceitação, aceitar, receber</strong> — SIG 962, 65 [séc. IV a.C.]; PEleph 29, 12 [séc. III a.C.]; PTebt 329, 19; BGU 194, 11 e outros; 2 Macc 6.19; 8.36; TestLevi 16.3 —: <span class=\"greek\">τὰς ἐπαγγελίας</span>, <strong>as promessas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.17</a>.</p>\n<p class=\"entry-text\"><strong>Assumir um fardo</strong> — Diodoro Sículo 15.51.1 <span class=\"greek\">ἀ. τ. πόλεμον</span>; compare Políbio 1.88.12; Plutarco, <em>Eumen.</em> 586 [6.3]; Epicteto 3.24.64; SIG 685, 30 [139 a.C.] <span class=\"greek\">ἀ. πᾶσαν κακοπαθίαν</span>; IXanthos 7, 67, 25s. <span class=\"greek\">ἀναδεξάμενος τὴν φροντίδα</span>; SB 7738, 13 <span class=\"greek\">πόνον ἀ.</span>; Josefo, <em>Bell.</em> 3.4; 14; Justino, <em>D.</em> 95.2 <span class=\"greek\">τὰς πάντων κατάρας</span> —: <span class=\"greek\">τὸ βάρος</span>, <strong>o fardo</strong>, Dg 10.6; <span class=\"greek\">τὰς ἁμαρτίας</span>, <strong>os pecados</strong>, 9.2 — compare Demóstenes 19.36 <span class=\"greek\">ἁμαρτήματα</span>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Estender hospitalidade a, receber, acolher hóspedes</strong>, frequentemente na linguagem diplomática, expressão do sistema greco-romano de reciprocidade — por exemplo OGI 339, 20 [séc. II a.C.] <span class=\"greek\">τάς τε πρεσβείας ἀνεδέχετο προθύμως</span> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.7</a>. — DELG s.v. <span class=\"greek\">δέχομαι</span>. M-M. TW. Spicq.</p>\n</section></article><article id=\"entry-anadidomi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναδίδωμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anadídōmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro 3ª sg. <span class=\"greek\">ἀναδώσει</span>, Sir 1.22; 2º aoristo <span class=\"greek\">ἀνέδωκα</span>, Justino; particípio do 2º aoristo <span class=\"greek\">ἀναδούς</span>; perfeito 3ª sg. <span class=\"greek\">ἀναδέδωκε</span>, Justino, <em>A II</em> 2.8. Píndaro e outros; inscrições, papiros; Sir 1.23; Josefo; Justino.</p>\n<p class=\"entry-text\"><strong>Entregar, passar, transmitir</strong>; <span class=\"greek\">τινί τι</span>, algo a alguém — Fílon, <em>Aet. M.</em> 62; Josefo, <em>Ant.</em> 1.249; <span class=\"greek\">βιβλίδιον</span>, Justino, <em>A I</em> 29.2; <em>A II</em> 2.8 —: <span class=\"greek\">ἀ. τὴν ἐπιστολὴν τῷ ἡγεμόνι</span>, <strong>entregar a carta ao governador</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.33</a>. O mesmo burocratês aparece em Políbio 29.10.7; Diodoro Sículo 11.45.3; IG XIV, 830, 22; PTebt 448; PFay 130, 15. Da transmissão de uma apologia a Adriano, Qua (1). — M-M.</p>\n</section></article><article id=\"entry-anazao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναζάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anazáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo <span class=\"greek\">ἀνέζησα</span>. Nicandro — séc. II a.C. — emprega a forma épica <span class=\"greek\">-ζώω</span>, Fgm. 70, 8 [Ateneu 4, 11 p. 133d]; Caríton 3.8.9; Artem. 4.82; Paradox. Flor. 6; CIG 2566, 2; JosAs 19.3 cód. A por <span class=\"greek\">ἀνεζωοπύρησαν</span>; Dssm., <em>LO</em> 75s. [<em>LAE</em> 94ss.]; Nägeli 47; DELG s.v. <span class=\"greek\">ζώω</span>. Sentido básico: <strong>voltar à vida</strong>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Passar de uma condição de morte para a vida.</strong> <strong>a.</strong> Literalmente, <strong>ser ressuscitado</strong>, como nas passagens citadas acima. Dos mortos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20.5</a> t.r., leitura erasmiana sem evidência manuscrita conhecida; veja RBorger, <em>TRu</em> 52, 1987, 57; ParJer 7.18. De Cristo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14.9</a> v.l.</p>\n<p class=\"entry-text\"><strong>b.</strong> Figuradamente, <strong>estar vivo novamente, reviver</strong>, de alguém moral e espiritualmente morto: <span class=\"greek\">ὁ υἱός μου νεκρὸς ἦν καὶ ἀνέζησεν</span>, <strong>meu filho estava morto e reviveu</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.24</a> — v.l. <span class=\"greek\">ἔζησεν</span> —; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">v. 32</a> v.l. — <span class=\"greek\">ἔζησεν</span> no texto.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Entrar em funcionamento depois de estar dormente, ganhar vida</strong>, com perda da força de <span class=\"greek\">ἀνά</span>; veja <span class=\"greek\">ἀναβλέπω</span> 2aβ. <span class=\"greek\">ἡ ἁμαρτία ἀνέζησεν</span>, <strong>o pecado ganhou vida</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7.9</a>. — M-M. TW.</p>\n</section></article><article id=\"entry-anazeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναζέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anazéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ζέω</span>, “ferver, fervilhar”; intransitivo — assim Sófocles, Hipócrates e outros; <em>Περὶ ὕψους</em> p. 67, 5 V. = 44, 4 [206 verso]; Plutarco, <em>Art.</em> 1019 [16.6], <em>Mor.</em> 728b; Êx 9.9, 10; 2 Macc 9.9. <strong>Ferver, borbulhar</strong>, de lama etc. no mundo inferior, ApcPt 16, 31.</p>\n</section></article><article id=\"entry-anazeteo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναζητέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anazētéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ζητέω</span>, “procurar”. Imperfeito <span class=\"greek\">ἀνεζήτουν</span>; 1º aoristo <span class=\"greek\">ἀνεζήτησα</span>, LXX; passivo 3ª sg. <span class=\"greek\">ἀνεζητήθη</span>, 2 Macc 13.21. Heródoto 1.137; Tucídides 2.8.3; inscrições, papiros, LXX; TestSol 12.1 C; TestAbr B 113, 26 [Stone p. 74]; Fílon, <em>Somn.</em> 2.61; Josefo; Justino, <em>D.</em> 5.6; Taciano 15.1.</p>\n<p class=\"entry-text\"><strong>Tentar localizar por meio de busca, procurar, buscar</strong>; <span class=\"greek\">τινά</span>, <strong>alguém</strong>. Nos papiros, de criminosos e escravos fugitivos — PHib 71, 9 [245/244 a.C.]; PCairZen 310, 4 [séc. III a.C.]; PRein 17, 13; PFlor 83, 12 —; também 2 Macc 13.21; Josefo, <em>Bell.</em> 3.340; <em>Ant.</em> 9.134. <span class=\"greek\">Σαῦλον</span>, <strong>Saulo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 11.25</a>. <span class=\"greek\">ἀνεζήτουν αὐτόν</span>, <strong>procuravam-no</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.44</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.45\" target=\"_blank\" rel=\"noopener noreferrer\">v. 45</a> — nesta última passagem, v.l. <span class=\"greek\">ζητοῦντες</span>. De uma obra literária perdida: MPol 22.3. — M-M.</p>\n</section></article><article id=\"entry-anazonnumi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναζώννυμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anazṓnnumi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ζώννυμι</span>, “cingir”. 1º aoristo médio <span class=\"greek\">ἀνεζωσάμην</span> — Dídimo Gramático, séc. I a.C./I d.C., em Ateneu 4.17, 139e; Pr 31.17 <span class=\"greek\">τὴν ὀσφύν</span>; Jz 18.16 B; Fílon, <em>Leg. All.</em> 2.28; 3.153.</p>\n<p class=\"entry-text\"><strong>Prender, cingir</strong>, literalmente, de roupas compridas presas para facilitar o trabalho ou a caminhada — Dio Crisóstomo 55 [72], 2 <span class=\"greek\">ἀνεζωσμένοι</span>; Aquiles Tácio 8.12.1; Jz 18.16 cód. B <span class=\"greek\">ἀνεζωσμένοι</span>; lat. <em>alte praecinctus</em>. Depois, figuradamente: <span class=\"greek\">ἀναζωσάμενοι τὰς ὀσφύας τῆς διανοίας ὑμῶν</span>, <strong>tendo cingido os lombos da vossa mente</strong>, isto é, <strong>preparados para agir</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1.13</a>; Pol 2.1.</p>\n</section></article><article id=\"entry-anazoopyreo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναζωοπυρέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anazōopuréō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma atestada em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1.6</a> cód. D e JosAs 19.3. Veja o verbete seguinte, <span class=\"greek\">ἀναζωπυρέω</span>.</p>\n</section></article><article id=\"entry-anazopyreo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναζωπυρέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anazōpuréō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ζωπυρέω</span>, “acender em chama”. 1º aoristo <span class=\"greek\">ἀνεζωπύρησα</span>. Literalmente, “fazer arder novamente”; geralmente figurado e, em nossa literatura, somente assim.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Transitivo — Platão, Xenofonte e outros —: <strong>fazer começar novamente, reacender algo</strong> — Plutarco, <em>Per.</em> 152 [1.4], <em>Pomp.</em> 645 [49.5]; Jâmblico, <em>Vi. Pyth.</em> 16.70; PGM 13, 739; Josefo, <em>Bell.</em> 1.444, passivo <span class=\"greek\">ὁ ἔρως</span>; <em>Ant.</em> 8.234; Irineu 3.11.8 [Harv II 47, 6]. <span class=\"greek\">τὸ χάρισμα τοῦ θεοῦ</span>, <strong>reacender o dom de Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1.6</a>. <span class=\"greek\">ἀναζωπυρησάτω ἡ πίστις αὐτοῦ</span>, <strong>que sua fé em Deus seja reacendida</strong>, 1 Cl 27.3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Intransitivo — Dionísio de Halicarnasso 7.54; Plutarco, <em>Timol.</em> 247 [24.1], <em>Pomp.</em> 640 [41.2]; Gn 45.27; 1 Macc 13.7; JosAs 19.3 cód. B <span class=\"greek\">ἀναζωοπύρησαν</span>; Josefo, <em>Ant.</em> 11.240 —: <strong>adquirir nova vida, acender-se em chama</strong>. <span class=\"greek\">ἀναζωπυρήσαντες ἐν αἵματι θεοῦ</span>, <strong>inflamados com nova vida pelo sangue de Deus</strong>, IEph 1.1. — Veja Anz 284s. — M-M.</p>\n</section></article><article id=\"entry-anathallo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀναθάλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦anathállō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">θάλλω</span>, “brotar, crescer”. 1º aoristo plural <span class=\"greek\">ἀνεθήλαμεν</span>, Justino, <em>D.</em> 119.3; 2º aoristo <span class=\"greek\">ἀνέθαλον</span> — W-S. §13, 10; B-D-F §101 s.v. <span class=\"greek\">θάλλειν</span>; Rob. 348.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Intransitivo: <strong>estar novamente num estado idêntico ao anterior, crescer novamente, florescer novamente</strong>. Literalmente, de plantas — por exemplo, escólio a Nicandro, <em>Ther.</em> 677; também Enomau em Eusébio, <em>PE</em> 5.34.14 fim, <span class=\"greek\">γῆ ἀνέθαλεν</span>, “a terra floresceu novamente”; PGM 4, 1611 —; também figuradamente — Aélio, <em>VH</em> 5.4; Sl 27.7; Sb 4.4; Sir 46.12; 49.10; Justino, <em>D.</em> 119.3 <span class=\"greek\">λαὸς ἕτερος ἀνεθήλαμεν</span>. <span class=\"greek\">ἡ ἐσκοτωμένη διάνοια ἡμῶν ἀναθάλλει εἰς τὸ φῶς</span>, <strong>nossa mente obscurecida cresce novamente para a luz</strong>, como uma planta, 1 Cl 36.2. Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4.10</a>, veja 2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Factitivo: <strong>fazer estar novamente num estado idêntico ao anterior, fazer crescer/florescer novamente</strong>, literalmente em Sir 50.10; Ez 17.24 e figuradamente em Sir 1.18; 11.22. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4.10</a>, tanto 1 como 2 são prováveis: <span class=\"greek\">ἀνεθάλετε τὸ ὑπὲρ ἐμοῦ φρονεῖν</span> pode significar ou <strong>revivestes, no que diz respeito ao vosso cuidado por mim</strong>, ou <strong>reavivastes o vosso cuidado por mim</strong>. — M-M.</p>\n</section></article><article id=\"entry-anathema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀνάθεμα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦anáthema⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Equivale a <span class=\"greek\">ἀνατεθειμένον</span>, de <span class=\"greek\">ἀνατίθημι</span>, “algo colocado” ou “erigido”; forma do grego helenístico para o mais antigo <span class=\"greek\">ἀνάθημα</span> — Homero e outros; Moeris 188; Phryn. 249 Lob.; veja índice de SIG.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Aquilo que é dedicado como oferta votiva, oferta votiva colocada num templo</strong> — Plutarco, <em>Pelop.</em> 291 [25.7]; 2 Macc 2.13; Fílon, <em>Mos.</em> 1.253 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21.5</a> v.l.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Aquilo que foi amaldiçoado; amaldiçoado, sob maldição</strong>. Na LXX, como regra, corresponde a <span class=\"hebrew\">חֵרֶם</span>: aquilo que é “devotado à divindade” pode ser tanto consagrado como amaldiçoado. Nas demais passagens do Novo Testamento, o sentido se move decididamente na direção deste último valor — como Nm 21.3; Dt 7.26; Js 6.17; 7.12; Jz 1.17; Zc 14.11, e também as tabuletas de maldição de Mégara, IDefixWünsch 1, 17.</p>\n<p class=\"entry-text\"><span class=\"greek\">οὐδεὶς ἐν πνεύματι θεοῦ λαλῶν λέγει· ἀνάθεμα Ἰησοῦς</span>, <strong>ninguém que fala pelo Espírito de Deus diz: “Jesus seja amaldiçoado”</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12.3</a>. Sobre o assunto, Laud. <em>Therap.</em> 22: <span class=\"greek\">ὅταν ὁ δαίμων ἀλλοιώσας τὸν ἐνεργούμενον, ἐκεῖνος ὅλος λαλεῖ, τὸ στόμα τοῦ πάσχοντος ἴδιον τεχναζόμενος ὄργανον</span>, isto é, quando a divindade altera aquele sobre quem atua, é a própria divindade que fala por inteiro, fazendo habilmente da boca do afetado seu próprio instrumento; NBrox, <em>BZ</em> n.s. 12, 1968, 103–11.</p>\n<p class=\"entry-text\">Como fórmula, <span class=\"greek\">ἀνάθεμα ἔστω</span>, <strong>seja anátema / seja amaldiçoado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.8s.</a>; para isso <span class=\"greek\">ἤτω ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16.22</a>. Do mesmo modo, <span class=\"greek\">ηὐχόμην ἀνάθεμα εἶναι αὐτὸς ἐγὼ ἀπὸ τοῦ Χριστοῦ</span>, <strong>eu poderia desejar que eu mesmo fosse amaldiçoado — e, portanto, separado — de Cristo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9.3</a> — CSchneider, “D. Volks-u. Heimatgefühl b. Pls”, <em>Christentum u. Wissensch.</em> 8, 1932, 1–14; PBratsiotis, “Eine Notiz zu Rö 9:3 u. 10:1”, <em>NovT</em> 5, 1962, 299s.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>O conteúdo expresso numa maldição, uma maldição</strong>. A expressão <span class=\"greek\">ἀναθέματι ἀνεθεματίσαμεν ἑαυτοὺς μηδενὸς γεύσασθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.14</a>, significa que os conspiradores se ligaram ao plano mediante juramento terrível, de modo que, caso falhassem, a maldição cairia sobre eles — <span class=\"greek\">ἀ. ἀναθεματίζειν</span> como em Dt 13.15; 20.17. Veja Dssm., <em>LO</em> 74 [<em>LAE</em> 92s.]; Nägeli 49; Schürer II 432s.; Billerb. IV 293–333, “D. Synagogenbann”.</p>\n<p class=\"entry-text\">Veja também <span class=\"greek\">ἀνάθημα</span>, grafia que frequentemente alterna com <span class=\"greek\">ἀνάθεμα</span> nos textos, na medida em que não se observa a distinção fina entre <span class=\"greek\">ἀνάθημα</span>, “oferta votiva”, e <span class=\"greek\">ἀνάθεμα</span>, “coisa amaldiçoada”. — GBornkamm, <em>Das Ende des Gesetzes</em><sup>4</sup>, 1963, 123–32; KHofmann, <em>RAC</em> I 427–30. — EDNT I 80s. M-M. TW. Sv.</p>\n</section></article>"};
